def transform_simple(grid):
    """
    Simplified rule based on task-35d6465a.json demo analysis:
    1. Value with ≥2 cells on same main diagonal (c-r constant) → fill entire main diagonal
    2. Value with ≥2 cells on same anti-diagonal (c+r constant) → stay at original positions
    3. Single cell → stay at original position
    """
    rows = len(grid)
    cols = len(grid[0])
    bg = grid[0][0]

    output = [[bg] * cols for _ in range(rows)]

    # Copy input to output
    for r in range(rows):
        for c in range(cols):
            output[r][c] = grid[r][c]

    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val == bg:
                continue

    # Group positions by diagonal
    main_diag_to_vals = {}  # (c-r) → {val: positions}
    anti_diag_to_vals = {}  # (c+r) → {val: positions}

    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val == bg:
                continue
            cr = c - r
            cs = c + r

            if cr not in main_diag_to_vals:
                main_diag_to_vals[cr] = {}
            if cs not in anti_diag_to_vals:
                anti_diag_to_vals[cs] = {}

            main_diag_to_vals[cr][val] = main_diag_to_vals[cr].get(val, []) + [(r, c)]
            anti_diag_to_vals[cs][val] = anti_diag_to_vals[cs].get(val, []) + [(r, c)]

    # Apply transformations
    # For main diagonals: ≥2 cells → fill entire diagonal
    for cr, vals in main_diag_to_vals.items():
        for val, positions in vals.items():
            if len(positions) >= 2:
                # Fill entire main diagonal
                for r in range(rows):
                    c = cr + r
                    if 0 <= c < cols:
                        output[r][c] = val

    # For anti-diagonals: ≥2 cells → stay at original (no change needed since we copied)
    # Actually we need to clear original positions if they're on anti-diag

    return output

# Test on demo input
