    main_diag_cells = {}

    for r in range(rows):
        for c in range(cols):
            val = grid[r][c]
            if val == bg:
                continue
            cr = c - r
            main_diag_cells.setdefault(cr, []).append((r, c))

    for cr, cells in main_diag_cells.items():
        val_to_positions = {}
        for pos in cells:
            val = grid[pos[0]][pos[1]]
            if val == bg:
                continue
            if val not in val_to_positions:
